   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'TableError';
    this.code = code;
  }
}

/**
 * Classify a single code point's display width.
 * @param {number} cp Code point.
 * @returns {number} 0, 1 or 2.
 */
function codePointWidth(cp) {
  if (cp < 0x0020 || cp === 0x007f) return 0;
  if ((cp >= 0x0300 && cp <= 0x036f) || cp === 0x200b || cp === 0x200c || cp === 0x200d || cp === 0xfeff) {
    return 0;
  }
  // Two-column ranges (inclusive).
  const wide = [
    [0x1100, 0x115f],
    [0x2e80, 0x303e],
    [0x3041, 0x33ff],
    [0x3400, 0x4dbf],
    [0x4e00, 0x9fff],
    [0xa000, 0xa4cf],
    [0xac00, 0xd7a3],
    [0xf900, 0xfaff],
    [0xfe10, 0xfe19],
    [0xfe30, 0xfe6f],
    [0xff00, 0xff60],
    [0xffe0, 0xffe6],
    [0x1f300, 0x1f64f],
    [0x1f900, 0x1f9ff],
    [0x20000, 0x2fffd],
    [0x30000, 0x3fffd],
  ];
  for (const [lo, hi] of wide) {
    if (cp >= lo && cp <= hi) return 2;
  }
  return 1;
}

