 * Display width of a string in terminal columns.
 *
 * @param {string} text Text to measure.
 * @returns {number} Column count.
 */
export function stringWidth(text) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  let width = 0;
  for (const cp of text) {
    const code = cp.codePointAt(0);
    width += codePointWidth(code);
  }
  return width;
}

/**
 * Break a single word (no spaces) into chunks of at most `width` columns.
 * A wide character that would straddle the boundary starts the next chunk.
 * Throws UNWRAPPABLE if any single character is wider than the column.
 *
 * @param {string} word Word with no spaces.
 * @param {number} width Column width.
 * @returns {string[]} Chunks.
