  const chunks = [];
  let current = '';
  let currentWidth = 0;
  for (const cp of word) {
    const code = cp.codePointAt(0);
    const w = codePointWidth(code);
    if (w > width) {
      throw new TableError('UNWRAPPABLE', 'character is wider than the column');
