    throw new TableError('BAD_ROWS', 'rows must be an array');
  }

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const cells = Array.isArray(row) ? row : [];
    if (cells.length !== numCols) {
      throw new TableError('BAD_ROW_LENGTH', `row ${i} has ${cells.length} cells, expected ${numCols}`);
