    for (let j = 0; j < cells.length; j++) {
      if (typeof cells[j] !== 'string') {
        throw new TableError('BAD_CELL', `cell at row ${i}, column ${j} is not a string`);
      }
    }
  }

  if (rows.length === 0) {
    return '';
  }

  // Wrap each cell.
  const wrappedRows = rows.map((row) => row.map((cell, col) => wrapCell(cell, widths[col])));

  // Determine line count per row (tallest cell).
  const lineCounts = wrappedRows.map((row) => Math.max(...row.map((lines) => lines.length)));

  const allLines = [];
  let rowIndex = 0;
  for (let r = 0; r < wrappedRows.length; r++) {
    const wrappedRow = wrappedRows[r];
    const lineCount = lineCounts[r];
